<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import type { SupplierForm, SupplierLineInput } from '@quote/contracts';
import { takeLinkToken } from './link';
import { restoreSubmission, retainPending, type SubmissionBody } from './pending';
const base=(import.meta.env.VITE_API_BASE_URL||'/api/v1').replace(/\/$/,'');
const form=ref<SupplierForm|null>(null), busy=ref(false), error=ref(''), unavailable=ref(false), loading=ref(true);
const review=ref(false), acknowledged=ref(false), validUntil=ref(''), notice=ref(''), confirmedNotFound=ref(false);
const answers=ref<Record<string,{status:''|'quoted'|'unavailable';unitPrice:string}>>({});
const token=ref(sessionStorage.getItem('supplier-session')||'');
const pendingStorageKey=()=>token.value?'supplier-pending-'+token.value:'supplier-pending';
const restored=restoreSubmission(sessionStorage.getItem(pendingStorageKey())||sessionStorage.getItem('supplier-pending'));
const pending=ref(restored?.key||'');
const pendingPayload=ref<SubmissionBody|null>(restored?.body||null);
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10);
const complete=computed(()=>form.value?.lines.filter(l=>answers.value[l.id]?.status==='unavailable'||answers.value[l.id]?.status==='quoted'&&validPrice(answers.value[l.id].unitPrice)).length||0);
const quotedCount=computed(()=>form.value?.lines.filter(l=>answers.value[l.id]?.status==='quoted').length||0);
function validPrice(value:string){return /^(0|[1-9]\d{0,9})(?:\.\d{1,2})?$/.test(value)&&Number(value)>0;}
function stamp(value:string){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.floor(Math.random()*16);return(c==='x'?r:(r&3)|8).toString(16);});}
class ApiError extends Error{constructor(public code:string,message:string,public unknown=false,public status?:number){super(message);}}
async function api<T>(path:string,method='GET',body?:unknown,key?:string):Promise<T>{
 let result:Response;try{result=await fetch(base+path,{method,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...(key?{'Idempotency-Key':key}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)});}catch{throw new ApiError('NETWORK_UNKNOWN','连接中断，尚未确认提交结果。请先核对结果。',true);}
 let envelope;try{envelope=await result.json();}catch{throw new ApiError('RESPONSE_UNKNOWN','服务响应无法确认，请先核对本次提交结果。',true);}if(!result.ok){if([401,403,410].includes(result.status)){unavailable.value=true;sessionStorage.removeItem('supplier-session');token.value='';}const unknown=result.status>=500||result.status===408||envelope?.error?.code==='BUSY_RETRY_REQUIRED';throw new ApiError(envelope?.error?.code||'HTTP_'+result.status,unknown?'服务响应异常，请先核对本次提交结果。':envelope?.error?.message||'暂时无法完成操作。',unknown,result.status);}if(typeof envelope!=='object'||envelope===null||!('data' in envelope))throw new ApiError('RESPONSE_UNKNOWN','服务响应无法确认，请先核对本次提交结果。',true);return envelope.data;
}
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function initializeAnswers(){if(!form.value)return;validUntil.value=form.value.submitted?.validUntil||'';answers.value=Object.fromEntries(form.value.lines.map(l=>{const previous=form.value?.submitted?.lines.find(a=>a.purchaseLineId===l.id);return [l.id,{status:previous?.status||'',unitPrice:previous?.unitPrice||''}];}));}
async function load(){form.value=await api<SupplierForm>('/supplier/quote');initializeAnswers();}
function mark(id:string,status:'quoted'|'unavailable'){if(busy.value||pending.value)return;answers.value[id].status=status;if(status==='unavailable')answers.value[id].unitPrice='';error.value='';}
function reviewSubmission(){if(busy.value||pending.value)return;error.value='';if(!validUntil.value||validUntil.value<today){error.value='请选择今天或之后的报价有效至日期。';return;}if(complete.value!==form.value?.lines.length){error.value='每行均须选择供货状态；可供货单价须大于 0，最多两位小数。';return;}review.value=true;acknowledged.value=false;window.scrollTo({top:0,behavior:'smooth'});}
function payload(){return {validUntil:validUntil.value,lines:form.value!.lines.map(l=>({purchaseLineId:l.id,status:answers.value[l.id].status as 'quoted'|'unavailable',unitPrice:answers.value[l.id].status==='quoted'?answers.value[l.id].unitPrice:null}))};}
function clearPending(){pending.value='';pendingPayload.value=null;sessionStorage.removeItem(pendingStorageKey());sessionStorage.removeItem('supplier-pending');confirmedNotFound.value=false;}
async function send(){if(!acknowledged.value||pending.value)return;await work(async()=>{pending.value=uuid();pendingPayload.value=payload();sessionStorage.setItem(pendingStorageKey(),JSON.stringify({key:pending.value,body:pendingPayload.value}));await doSubmit();});}
async function doSubmit(){try{form.value=await api<SupplierForm>('/supplier/quote','POST',pendingPayload.value,pending.value);clearPending();review.value=false;initializeAnswers();notice.value='本次报价已提交';window.scrollTo({top:0,behavior:'smooth'});}catch(e){if(e instanceof ApiError&&!retainPending(e.status,e.unknown))clearPending();throw e;}}
async function checkResult(){await work(async()=>{const result=await api<{status:'committed'|'not_found'}>('/operations/'+pending.value);if(result.status==='committed'){await load();clearPending();review.value=false;notice.value='已核实：本次报价提交成功。';}else{confirmedNotFound.value=true;notice.value='暂未查到提交结果，请继续核对或按原操作键重试同一次提交。';}});}
async function retry(){if(!pendingPayload.value){error.value='旧记录缺少原提交内容，请保留待核对并联系销售核实。';return;}await work(doSubmit);}
onMounted(async()=>{try{const raw=takeLinkToken(location.hash,()=>history.replaceState(null,'',location.pathname+location.search));if(raw){sessionStorage.removeItem('supplier-session');token.value='';const session=await api<{sessionToken:string;expiresAt:string}>('/supplier/session','POST',{token:raw});token.value=session.sessionToken;sessionStorage.setItem('supplier-session',session.sessionToken);const saved=restoreSubmission(sessionStorage.getItem(pendingStorageKey()));pending.value=saved?.key||'';pendingPayload.value=saved?.body||null;}if(!token.value){unavailable.value=true;error.value='未找到有效填写链接，请联系销售获取本次询价链接。';return;}await load();}catch(e){error.value=(e as Error).message;if(!token.value)unavailable.value=true;}finally{loading.value=false;}});
</script>

<template>
 <main>
  <header><span class="brand">饮片报价</span><span>本次厂家报价</span></header>
  <section v-if="loading" class="state" role="status"><h1>正在读取询价明细</h1><p>请稍候…</p></section>
  <section v-else-if="unavailable" class="state"><span class="state-mark">!</span><h1>填写链接暂不可用</h1><p>{{error}}</p><p>请联系销售确认本次有效链接。</p><p v-if="pending">本次提交结果仍待核实，请联系销售核对，勿重复填写。</p></section>
  <template v-else-if="form">
   <section class="context"><span class="eyebrow">采购修订 R{{form.revisionNo}} · 接收 {{form.receivedDate}}</span><h1>{{form.submitted?'本次报价已提交':review?'核对本次报价':'本次厂家报价'}}</h1><p class="manufacturer">{{form.manufacturerName}}</p><p v-if="form.submitted" class="note">提交后只读。需要更正时，请联系销售重新询价。</p><template v-else><div class="deadline"><span>填写链接截止 · 北京时间</span><strong>{{stamp(form.linkExpiresAt)}}</strong></div><p class="basis">所有报价均为含税、含抽点单价，单位 元/kg。</p></template></section>
   <section v-if="form.submitted" class="receipt">
    <dl><dt>提交编号</dt><dd>{{form.submitted.id}}</dd><dt>报价有效至</dt><dd>{{form.submitted.validUntil}}（含当日）</dd></dl>
    <article v-for="(line,index) in form.lines" :key="line.id" class="quote-line"><div class="line-head"><span class="index">{{String(index+1).padStart(2,'0')}}</span><div><h2>{{line.name}}</h2><p>{{line.spec||'未提供规格'}}</p></div><span class="quantity">{{line.quantity}} <small>kg</small></span></div><div class="receipt-price"><span>{{form.submitted.lines.find(a=>a.purchaseLineId===line.id)?.status==='quoted'?'可供货':'无法供货'}}</span><strong>{{form.submitted.lines.find(a=>a.purchaseLineId===line.id)?.status==='quoted'?form.submitted.lines.find(a=>a.purchaseLineId===line.id)?.unitPrice+' 元/kg':'单价不适用'}}</strong></div></article>
   </section>
   <section v-else-if="review" class="review">
    <dl class="review-meta"><dt>报价有效至</dt><dd>{{validUntil}}（含当日）</dd><dt>供货情况</dt><dd>{{quotedCount}} 行可供货 / {{form.lines.length-quotedCount}} 行无法供货</dd></dl>
    <article v-for="line in form.lines" :key="line.id" class="review-line"><div><h2>{{line.name}}</h2><p>{{line.spec||'未提供规格'}} · {{line.quantity}} kg</p></div><strong>{{answers[line.id].status==='quoted'?answers[line.id].unitPrice+' 元/kg':'无法供货'}}</strong></article>
    <label class="ack"><input type="checkbox" v-model="acknowledged" :disabled="busy||!!pending"><span>我已核对全部供货状态、含税含抽点单价和有效期，确认提交后不可修改。</span></label>
    <div class="actions"><button class="secondary" @click="review=false" :disabled="busy||!!pending">返回修改</button><button class="primary" @click="send" :disabled="busy||!acknowledged||!!pending">{{busy?'正在提交…':'确认提交'}}</button></div>
   </section>
   <form v-else @submit.prevent="reviewSubmission" novalidate>
    <section class="validity"><label for="valid-until">报价有效至日期</label><input id="valid-until" type="date" v-model="validUntil" :min="today" :disabled="busy||!!pending"><p>含所选当天；与填写链接的截止时间分开。</p></section>
    <div class="section-head"><h2>采购明细</h2><span>{{form.lines.length}} 行 · 数量及规格只读</span></div>
    <article v-for="(line,index) in form.lines" :key="line.id" class="quote-line"><div class="line-head"><span class="index">{{String(index+1).padStart(2,'0')}}</span><div><h2>{{line.name}}</h2><p>规格：{{line.spec||'未提供'}}</p></div><span class="quantity">{{line.quantity}} <small>kg</small></span></div>
     <fieldset :disabled="busy||!!pending"><legend>{{line.name}} · 供货状态</legend><div class="choices"><label :class="{selected:answers[line.id].status==='quoted'}"><input type="radio" :name="line.id" :checked="answers[line.id].status==='quoted'" @change="mark(line.id,'quoted')">可供货</label><label :class="{selected:answers[line.id].status==='unavailable'}"><input type="radio" :name="line.id" :checked="answers[line.id].status==='unavailable'" @change="mark(line.id,'unavailable')">无法供货</label></div></fieldset>
     <label class="price" v-if="answers[line.id].status==='quoted'"><span>含税含抽点单价</span><div><input v-model="answers[line.id].unitPrice" :aria-label="line.name+' 含税含抽点单价'" type="text" inputmode="decimal" placeholder="填写单价" autocomplete="off" :disabled="busy||!!pending"><span>元/kg</span></div></label><p v-if="answers[line.id].status==='unavailable'" class="missing">本行无法供货，单价留空。</p>
    </article>
    <div class="actions sticky"><div class="progress">已完成 {{complete}} / {{form.lines.length}} 行<small>逐行报价或标记无法供货</small></div><button class="primary" type="submit" :disabled="busy||!!pending">核对并提交</button></div>
   </form>
   <p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="error" class="error" role="alert">{{error}}</p>
   <section v-if="pending" class="pending"><h2>提交结果待核实</h2><p>请先核对结果，避免重复报价。</p><button class="secondary" @click="checkResult" :disabled="busy">核对提交结果</button><button v-if="confirmedNotFound&&pendingPayload" class="primary" @click="retry" :disabled="busy">重试同一次提交</button><p v-if="confirmedNotFound&&!pendingPayload">旧记录缺少原提交内容，请保留待核对并联系销售核实。</p></section>
  </template>
  <section v-else-if="error" class="state"><h1>暂时无法读取询价</h1><p>{{error}}</p><button class="secondary" @click="work(load)" :disabled="busy">重新读取</button></section>
  <footer>仅用于本次厂家询价 · 请勿转发填写链接</footer>
 </main>
</template>

<style>
:root{font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;color:#243129;background:#fff;font-synthesis:none;font-size:15px;line-height:1.6}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{min-height:46px;border-radius:5px;cursor:pointer;padding:10px 15px;line-height:24px;border:1px solid transparent;transition:background .16s,opacity .16s}button:disabled{opacity:.45;cursor:default}button:focus-visible,input:focus-visible{outline:3px solid #93b69d;outline-offset:3px}main{max-width:680px;margin:auto;padding:0 22px calc(16px + env(safe-area-inset-bottom))}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e0e7df;min-height:68px;color:#748077;font-size:11px}.brand{font-size:18px;color:#216349;font-weight:650;letter-spacing:1px}.context{padding:30px 0 20px}.eyebrow{font-size:11px;color:#748077}h1{font-size:27px;line-height:1.35;letter-spacing:-.6px;margin:7px 0 12px;font-weight:600}.manufacturer{font-size:15px;margin:0 0 20px}.deadline{border-left:2px solid #ae8250;padding:10px 14px;background:#faf6ef;color:#85623a;font-size:11px}.deadline strong{display:block;font-size:15px;font-weight:500}.basis{font-size:12px;color:#216349;margin:20px 0 0}.note{font-size:13px;color:#748077}.validity{border-top:1px solid #e0e7df;border-bottom:1px solid #e0e7df;padding:23px 0}.validity label{display:block;font-size:13px;font-weight:550;margin-bottom:8px}.validity input{width:100%;min-height:46px;border:1px solid #cdd9ce;border-radius:5px;padding:10px 12px;background:#fff;color:#243129;appearance:none}.validity p,.line-head p{font-size:11px;color:#748077;margin:6px 0 0}.section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-top:24px}.section-head h2{font-size:15px;font-weight:600;margin:0}.section-head span{font-size:10px;color:#748077}.quote-line{border-bottom:1px solid #e0e7df;padding:24px 0}.line-head{display:flex;gap:12px;align-items:flex-start;margin-bottom:18px}.line-head h2,.review-line h2{font-size:18px;font-weight:550;margin:0}.index{font-size:10px;color:#748077;padding-top:5px}.quantity{margin-left:auto;white-space:nowrap;font-size:16px;font-variant-numeric:tabular-nums}.quantity small{font-size:11px;color:#748077}fieldset{border:0;padding:0;margin:0;min-width:0}legend{font-size:11px;color:#748077;margin-bottom:8px}.choices{display:flex;gap:12px}.choices label{display:flex;align-items:center;justify-content:center;gap:8px;flex:1;min-height:46px;border:1px solid #d3dfd2;border-radius:5px;font-size:14px;cursor:pointer;transition:background .16s,border-color .16s}.choices .selected{border-color:#216349;background:#edf4ef;color:#216349}input[type=radio],input[type=checkbox]{accent-color:#216349;width:17px;height:17px;flex:none;margin:0}.price{display:block;margin-top:17px;animation:enter .16s ease-out}.price>span{display:block;font-size:11px;color:#748077;margin-bottom:6px}.price>div{display:flex;align-items:center;border:1px solid #cdd9ce;border-radius:5px;overflow:hidden}.price input{border:0;min-width:0;flex:1;min-height:46px;padding:10px 12px;color:#243129;background:#fff;font-size:18px}.price div span{padding-right:12px;font-size:11px;color:#748077}.missing{font-size:11px;color:#85623a;margin:14px 0 0}.actions{display:flex;align-items:center;gap:14px;padding:18px 0 calc(18px + env(safe-area-inset-bottom));margin-top:12px}.actions button{flex:1}.sticky{position:sticky;bottom:0;background:#fffffff5;border-top:1px solid #e0e7df;z-index:1}.primary{background:#216349;color:white}.secondary{background:white;color:#216349;border-color:#cdd9ce}.progress{font-size:13px;flex:1}.progress small{display:block;font-size:10px;color:#748077}.error{color:#a04435;background:#fbf3ef;padding:12px;font-size:13px}.notice{color:#216349;background:#edf4ef;padding:12px;font-size:13px}.state{text-align:center;padding:70px 5px;min-height:60vh}.state h1{font-size:23px}.state p{font-size:13px;color:#748077}.state-mark{display:grid;place-items:center;margin:0 auto 24px;width:50px;height:50px;border:1px solid #d3dfd2;border-radius:50%;color:#85623a;font-size:24px}.receipt dl,.review-meta{display:grid;grid-template-columns:105px minmax(0,1fr);gap:8px;font-size:12px;padding:20px 0;border-bottom:1px solid #e0e7df;margin:0}.receipt dt,.review-meta dt{color:#748077}.receipt dd,.review-meta dd{margin:0;overflow-wrap:anywhere}.receipt-price{display:flex;justify-content:space-between;font-size:13px}.receipt-price strong{font-weight:550}.review-line{display:flex;justify-content:space-between;align-items:center;gap:10px;border-bottom:1px solid #e0e7df;padding:18px 0}.review-line h2{font-size:16px}.review-line p{font-size:11px;color:#748077;margin:3px 0 0}.review-line strong{font-size:14px;white-space:nowrap;font-weight:550}.ack{display:flex;align-items:flex-start;gap:10px;padding:25px 0 8px;font-size:12px}.ack input{margin-top:3px}.pending{padding:20px 0;border-top:2px solid #a27545}.pending h2{font-size:16px}.pending p{font-size:12px;color:#748077}.pending button{width:100%;margin:6px 0}footer{border-top:1px solid #e0e7df;text-align:center;color:#748077;font-size:10px;padding:20px 0;margin-top:24px}@keyframes enter{from{opacity:.4;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}@media(min-width:720px){main{padding-left:36px;padding-right:36px}.context{padding-top:40px}.quote-line{padding:28px 0}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
